  4717	md_process_table_row(MD_CTX* ctx, MD_BLOCKTYPE cell_type, OFF beg, OFF end,
  4718	                     const MD_ALIGN* align, int col_count)
  4719	{
  4720	    MD_LINE line;
  4721	    OFF* pipe_offs = NULL;
  4722	    int i, j, k, n;
  4723	    int ret = 0;
  4724	
  4725	    line.beg = beg;
  4726	    line.end = end;
  4727	
  4728	    /* Break the line into table cells by identifying pipe characters who
  4729	     * form the cell boundary. */
  4730	    MD_CHECK(md_analyze_inlines(ctx, &line, 1, TRUE));
  4731	
  4732	    /* We have to remember the cell boundaries in local buffer because
  4733	     * ctx->marks[] shall be reused during cell contents processing. */
  4734	    n = ctx->n_table_cell_boundaries + 2;
  4735	    pipe_offs = (OFF*) malloc(n * sizeof(OFF));
  4736	    if(pipe_offs == NULL) {
  4737	        MD_LOG("malloc() failed.");
  4738	        ret = -1;
  4739	        goto abort;
  4740	    }
  4741	    j = 0;
  4742	    pipe_offs[j++] = beg;
  4743	    for(i = ctx->table_cell_boundaries_head; i >= 0; i = ctx->marks[i].next) {
  4744	        MD_MARK* mark = &ctx->marks[i];
  4745	        pipe_offs[j++] = mark->end;
  4746	    }
  4747	    pipe_offs[j++] = end+1;
  4748	
  4749	    /* Process cells. */
  4750	    MD_ENTER_BLOCK(MD_BLOCK_TR, NULL);
  4751	    k = 0;
  4752	    for(i = 0; i < j-1  &&  k < col_count; i++) {
  4753	        if(pipe_offs[i] < pipe_offs[i+1]-1)
  4754	            MD_CHECK(md_process_table_cell(ctx, cell_type, align[k++], pipe_offs[i], pipe_offs[i+1]-1));
  4755	    }
  4756	    /* Make sure we call enough table cells even if the current table contains
  4757	     * too few of them. */
  4758	    while(k < col_count)
  4759	        MD_CHECK(md_process_table_cell(ctx, cell_type, align[k++], 0, 0));
  4760	    MD_LEAVE_BLOCK(MD_BLOCK_TR, NULL);
  4761	
  4762	abort:
  4763	    free(pipe_offs);
  4764	
  4765	    ctx->table_cell_boundaries_head = -1;
  4766	    ctx->table_cell_boundaries_tail = -1;
  4767	
  4768	    return ret;
  4769	}
